INSERT INTO boarding_exceptions (from_poi_id, to_poi_id, route_no, depart_time, node_id, stop_name, lat, lng,
  distance_m, gap_m, note)
SELECT f.poi_id, t.poi_id, v.route_no, v.depart::time, v.node_id, v.stop_name, v.lat::numeric(11,8),
  v.lng::numeric(11,8), v.dist::int, v.gap::int, v.note
FROM (VALUES
  ('김영삼 생가','고현터미널','32','06:00','GJB283','대계마을',34.93074,128.71512667,95,NULL,'고현 05:35 출발 편 — 송정→대계마을입구→대계마을→외포·장목·하청→고현 06:50(TAGO GJB846)'),
  ('김영삼 생가','고현터미널','32','20:55','GJB252','대계마을',34.93074,128.71503333,95,NULL,'고현 20:02 출발 편 — 외포→대계마을→국산·송정→고현 21:30(TAGO GJB814)'),
  ('매미성','고현터미널','32','20:37','GJB1621','대금교차로',34.9672817,128.7029844,218,6,'고현 20:02 출발 편 — 외포·대계·송정을 돌아 고현 21:30(TAGO GJB814)이라 길 건너편 정류소에서 탄다'),
  ('맹종죽테마공원','고현터미널','32','20:22','GJB46','와항마을',34.967825,128.65007667,47,7,'고현 20:02 출발 편 — 하청·와항마을에서 대금·외포·대계를 돌아 고현 21:30(TAGO GJB814)이라 길 건너편 정류소에서 탄다')
) AS v(from_name, to_name, route_no, depart, node_id, stop_name, lat, lng, dist, gap, note)
JOIN pois f ON f.short_name = v.from_name AND (f.theme IS NOT NULL OR f.poi_kind = 'TERMINAL')
JOIN pois t ON t.short_name = v.to_name AND (t.theme IS NOT NULL OR t.poi_kind = 'TERMINAL')
ON CONFLICT (from_poi_id, to_poi_id, route_no, depart_time) DO NOTHING;

-- 이름 조인에서 조용히 빠진 행이 없는지 확인한다(스팟 짧은 이름이 바뀌었으면 여기서 멈춘다).
DO $$ BEGIN
  IF (SELECT count(*) FROM boarding_stops) <> 235 THEN
    RAISE EXCEPTION 'V26: 타는 정류장 235행이 아니다'; END IF;
  IF (SELECT count(*) FROM boarding_exceptions) <> 4 THEN
    RAISE EXCEPTION 'V26: 예외 편 4행이 아니다'; END IF;
END $$;
